# ============================================================================
# PART 2. FLAT VIEWS  (built automatically from LIBRARY - do not edit by hand)
# ============================================================================
SKILLS = {}      # English name -> [aliases]   (the exact format keyword_extractor.py uses)
NAMES_FR = {}    # English name -> French name
DOMAIN_OF = {}   # English name -> domain id

for _domain_id, _domain in LIBRARY.items():
    for _name_en, (_name_fr, _aliases) in _domain["skills"].items():
        if _name_en in SKILLS:
            raise ValueError(f"Skill '{_name_en}' is listed twice: in '{DOMAIN_OF[_name_en]}' and in '{_domain_id}'")
        SKILLS[_name_en] = list(dict.fromkeys(_aliases))      # drop exact repeats, keep order
        NAMES_FR[_name_en] = _name_fr
        DOMAIN_OF[_name_en] = _domain_id


def skill_name(skill, lang="en"):
    """The name of a skill in English ('en') or French ('fr')."""
    return NAMES_FR.get(skill, skill) if lang == "fr" else skill


def domain_name(domain_id, lang="en"):
    """The name of a work domain in English ('en') or French ('fr')."""
    return LIBRARY[domain_id][lang]


