# ============================================================================
# PART 4. TOOLS: cleaning, health check, export
# ============================================================================
import unicodedata as _ud


def clean(text):
    """Make text easy to search: lowercase, fancy quotes and dashes -> plain ones,
    ligatures split (œ -> oe), and accents removed (é -> e).
    The extractor uses this same function, so the library and the texts always agree."""
    text = text.lower()
    for fancy, plain in (("‑", "-"), ("‐", "-"), ("–", "-"), ("—", "-"),
                         ("’", "'"), ("‘", "'"), (" ", " "), (" ", " "),
                         ("œ", "oe"), ("æ", "ae")):
        text = text.replace(fancy, plain)
    text = _ud.normalize("NFKD", text)
    return "".join(ch for ch in text if not _ud.combining(ch))


def check_library():
    """Health check. Prints counts and the problems worth fixing."""
    problems = 0
    n_aliases = sum(len(a) for a in SKILLS.values())
    print(f"{len(LIBRARY)} domains, {len(SKILLS)} skills, {n_aliases} aliases\n")
    for dom_id, dom in LIBRARY.items():
        print(f"  {len(dom['skills']):>3}  {dom['en']}  |  {dom['fr']}")

    # 1. the same alias (after cleaning) in two different skills
    owner = {}
    print("\nSame alias in two skills (each alias should point to one skill):")
    for name, aliases in SKILLS.items():
        for alias in aliases:
            key = clean(alias)
            if key in owner and owner[key] != name:
                print(f"  - '{alias}'  ->  '{owner[key]}'  AND  '{name}'")
                problems += 1
            owner.setdefault(key, name)

    # 2. RELATED must only use names that exist
    print("\nRELATED names that are not in the library:")
    for key, values in RELATED.items():
        for name in [key] + values:
            if name not in SKILLS:
                print(f"  - '{name}'")
                problems += 1

    # 3. very short aliases: fine, but worth a look if you see false hits
    short_ones = sorted({clean(a) for al in SKILLS.values() for a in al if len(clean(a)) <= 2})
    print(f"\nVery short aliases to keep an eye on ({len(short_ones)}): {', '.join(short_ones)}")
    print(f"\n{'OK, no problems found.' if problems == 0 else f'{problems} problem(s) to fix.'}")
    return problems


def export(json_path="skills_library.json", csv_path="skills_library.csv"):
    """Write the library as JSON (for a web app) and CSV (to open in Excel)."""
    import json
    import csv
    data = {dom_id: {"en": dom["en"], "fr": dom["fr"],
                     "skills": [{"en": en, "fr": fr, "aliases": al}
                                for en, (fr, al) in dom["skills"].items()]}
            for dom_id, dom in LIBRARY.items()}
    with open(json_path, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
    with open(csv_path, "w", encoding="utf-8-sig", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["domain_id", "domain_en", "domain_fr", "skill_en", "skill_fr", "aliases"])
        for dom_id, dom in LIBRARY.items():
            for en, (fr, al) in dom["skills"].items():
                writer.writerow([dom_id, dom["en"], dom["fr"], en, fr, " | ".join(al)])
    print(f"Saved: {json_path} and {csv_path}")


if __name__ == "__main__":
    import sys
    if len(sys.argv) > 1 and sys.argv[1] == "export":
        export()
    else:
        check_library()
